      setIsPairingModalOpen(false);
    } finally {
      setIsLoadingPairingParticipants(false);
    }
  };

  const handleOrganizerPairing = async (selection: {
    participant1Id: string;
    participant2Id: string;
    teamName?: string;
  }): Promise<boolean> => {
    if (isPairing || registrationLocked) return false;
    setIsPairing(true);
    try {
      try {
        await tournamentsApi.pairTournamentParticipants(tournament.id, selection);
      } catch (error) {
        const { getErrorMessage } = await import('@/utils/error');
        toast.error(getErrorMessage(error));
        return false;
      }

      setIsPairingModalOpen(false);
      toast.success(registrationTranslate('pairingSuccess', { count: 1 }));
      try {
        await refetchDivisionData?.();
      } catch (error) {
        const { getErrorMessage } = await import('@/utils/error');
        toast.error(getErrorMessage(error));
      }
      return true;
    } finally {
      setIsPairing(false);
    }
  };

  /**
   * Tournament-wide random pairing. The request body carries no division, so the
   * result is reported exactly as the server returned it: the pair count and the
   * leftover count both come from the response body, never from local state.
   */
  const handleGenerateRandomPairs = async (): Promise<RandomPairingOutcome> => {
    if (isPairing || registrationLocked) return 'failed';
    setIsPairing(true);
    try {
      let response: LiteGeneratePairsResponse;
      try {
        // The shared axios client already returns the HTTP body. This endpoint
        // answers with the flat generate payload, while the api layer still names
        // the `ApiResponse` envelope, so normalise once at this boundary.
        const result = await tournamentsApi.generateTournamentPairs(tournament.id, { strategy: 'RANDOM' });
        response = result.data ?? result;
      } catch (error) {
        const { getErrorMessage } = await import('@/utils/error');
        toast.error(getErrorMessage(error));
        return 'failed';
      }

      const pairedCount = response.paired.length;
      const unpairedCount = response.unpairedParticipantIds.length;
      // A 2xx that formed nothing is neither a success nor an error: the organizer
      // keeps the picker, the search and the selection, and the manual path stays.
      if (pairedCount === 0) return 'none';

      setIsPairingModalOpen(false);
      // The backend message is hardcoded Vietnamese, so the count comes from the
      // response while the wording comes from the active locale.
      toast.success(registrationTranslate('pairingSuccess', { count: pairedCount }));
      if (unpairedCount > 0) {
        toast(registrationTranslate('pairingUnpairedNotice', { count: unpairedCount }));
      }
      try {
        await refetchDivisionData?.();
      } catch (error) {
        const { getErrorMessage } = await import('@/utils/error');
        toast.error(getErrorMessage(error));
      }
      return 'formed';
    } finally {
      setIsPairing(false);
    }
  };
  return (
    <div className="w-full space-y-6 animate-in fade-in duration-200">
      {/* REGISTRATION MAIN CONTENT */}
      <div id="manage-participants-section" className="w-full space-y-4 min-w-0 max-w-full overflow-hidden transition-all">
          {/* Control Bar: Bên trái là Filter & Search, Bên phải là nút cài đặt (3-dots) */}
          <div className="flex items-center justify-between gap-3 pb-1">
            {/* Bên trái: Filter lọc và Search */}
            <div className="flex items-center gap-2">
              {/* Filter Dropdown (borderless, không khung) */}
              {(() => {
                const filterOptions = [
                  { value: 'ALL', label: registrationTranslate('filterAll'), count: participantSummary.total },
                  { value: 'PENDING', label: registrationTranslate('filterPending'), count: participantSummary.pending },
                  { value: 'COMPLETE', label: registrationTranslate('filterApproved'), count: participantSummary.approved },
                  { value: 'UNPAID', label: registrationTranslate('unpaidStatus'), count: participantSummary.unpaid },
                  { value: 'REJECTED', label: registrationTranslate('filterRejected'), count: participantSummary.rejected },
                ] as const;

                const currentOption = filterOptions.find((opt) => opt.value === filter) || filterOptions[0];

                return (
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <button
                        type="button"
                        className="inline-flex h-8 items-center gap-1.5 px-2.5 rounded-lg hover:bg-slate-100 text-xs font-bold text-slate-700 transition-colors cursor-pointer shrink-0"
                      >
                        <span>{currentOption.label}</span>
                        <span className="px-1.5 py-0.5 rounded-full text-xs font-bold bg-slate-100 text-slate-700">
                          {currentOption.count}
                        </span>
                        <ChevronDown className="w-3.5 h-3.5 text-slate-400" />
                      </button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="w-52 bg-white border border-slate-200 shadow-lg rounded-xl p-1.5 z-50">
                      {filterOptions.map((opt) => (
                        <DropdownMenuItem
                          key={opt.value}
                          onClick={() => setFilter(opt.value as typeof filter)}
                          className={cn(
                            'flex items-center justify-between px-3 py-2 text-xs font-semibold rounded-lg cursor-pointer transition-colors',
                            filter === opt.value
                              ? 'bg-blue-50 text-blue-700 font-bold'
                              : 'text-slate-700 hover:bg-slate-100 hover:text-slate-900'
                          )}
                        >
                          <span className="flex items-center gap-2">
                            {filter === opt.value && <Check className="w-3.5 h-3.5 text-blue-600" />}
                            <span className={filter === opt.value ? 'font-bold' : 'font-medium'}>{opt.label}</span>
                          </span>
                          <span
                            className={cn(
                              'px-1.5 py-0.5 rounded-full text-xs font-bold',
                              filter === opt.value ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                            )}
                          >
                            {opt.count}
                          </span>
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                );
              })()}

              {/* Search Input: bo tròn & height thấp */}
              <div className="w-full sm:w-60 md:w-64">
                <Input
                  value={search}
                  onChange={(event) => setSearch(event.target.value)}
                  placeholder={registrationTranslate('searchTeamMembers')}
                  icon={<Search className="h-3.5 w-3.5" />}
                  className="h-8 rounded-full text-xs pl-8 border-slate-200 focus-visible:ring-1"
                />
              </div>
            </div>

            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={registrationLocked}
              onClick={() => setIsRosterImportOpen(true)}
              className="h-8 gap-1.5 rounded-lg border-emerald-200 px-2.5 text-xs font-bold text-emerald-700 hover:bg-emerald-50"
              title={registrationTranslate('importExcel')}
            >
              <Upload className="h-3.5 w-3.5" />
              {registrationTranslate('importExcel')}
            </Button>

            {hasTournamentDoubles && (
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={isPairing || registrationLocked}
                onClick={() => void handleOpenPairing()}
                className="h-8 gap-1.5 rounded-lg border-blue-200 px-2.5 text-xs font-bold text-blue-700 hover:bg-blue-50"
                // The entry does the same tournament-wide thing whatever the
