import { api } from "@/lib/axios";
import type { AxiosRequestConfig } from "axios";
import { Category } from "@/types/category";
import {
  Tournament,
  ParentTournament,
  PaginatedTournaments,
  TournamentParticipant,
  BracketStage,
  BracketMatch,
  MatchTypeUI,
  MatchTypeDB,
  GenderRestriction,
  LiteParticipant,
  LiteGeneratePairsResponse,
  LiteUnpairResponse,
  type StageRoundConfig,
  type TournamentDivisionCapacity,
} from "@/types/tournament";
import { ApiResponse } from "@/types/api";
import type { OpsAuditLogResponse } from "@/features/organizer/ops/types";
import type { RosterColumnSlot } from "@/utils/exportTournament";

export type BracketSlotMutationOperation =
  "ASSIGN" | "MOVE" | "REPLACE" | "UNASSIGN" | "SWAP";
export type BracketSlotMutationSlot = "participant1" | "participant2";

export interface BracketSlotMutation {
  operation: BracketSlotMutationOperation;
  matchId?: string;
  slot?: BracketSlotMutationSlot;
  participantId?: string;
  fromMatchId?: string;
  fromSlot?: BracketSlotMutationSlot;
  toMatchId?: string;
  toSlot?: BracketSlotMutationSlot;
}

export interface UpdateBracketSlotsResponse {
  success: boolean;
  updatedMatchIds: string[];
  matches: BracketMatch[];
}

export const SPONSOR_TIERS = [
  "TITLE",
  "DIAMOND",
  "GOLD",
  "SILVER",
  "BRONZE",
  "IN_KIND",
] as const;
export type SponsorTier = (typeof SPONSOR_TIERS)[number];
export type SponsorStatus = "DRAFT" | "PUBLISHED" | "HIDDEN" | "ARCHIVED";

export interface TournamentSponsor {
  id: string;
  tournamentId?: string;
  displayName: string;
  tier: SponsorTier;
  logoUrl: string;
  websiteUrl: string | null;
  shortDescription: string | null;
  displayOrder: number;
  status?: SponsorStatus;
  isPublic?: boolean;
  startAt?: string | null;
  endAt?: string | null;
  createdAt?: string;
  updatedAt?: string;
}

export type SponsorPayload = Omit<
  TournamentSponsor,
  "id" | "tournamentId" | "createdAt" | "updatedAt" | "status"
> & { status?: Exclude<SponsorStatus, "ARCHIVED"> };

export interface StaffMember {
  userId: string;
  role: "CO_ORGANIZER" | "REFEREE" | "SPECTATOR";
  fullName: string;
  email: string;
  avatarUrl: string | null;
}

export interface WorkspaceRefereeInvite {
  refereeId: string;
  tournamentId: string;
  tournamentName: string;
  logoUrl?: string | null;
  tournamentStatus: string;
  categoryName: string | null;
  assignedAt: string;
  status: "INVITED" | "ACCEPTED" | "DECLINED";
}

export interface TournamentReferee {
  id: string;
  userId: string;
  status: string;
  fullName: string;
  email: string;
  avatarUrl: string | null;
  invitedByName: string | null;
  invitedByAvatarUrl: string | null;
}

export interface TournamentCourt {
  id: string;
  venueId: string;
  courtName: string;
  status: "AVAILABLE" | "MAINTENANCE" | string;
}

export interface TournamentCourtsResponse {
  venue: {
    id: string;
    name: string;
    locationAddress: string;
  } | null;
  courts: TournamentCourt[];
}

export interface SchedulePlanAssignment {
  matchId: string;
  courtId: string;
  scheduledAt: string;
}

export interface AiScheduleCommandInput {
  command: string;
  date: string;
  courtIds: string[];
  divisionId?: string;
  gridIncrementMinutes?: 5 | 10 | 15 | 30 | 60;
  locale?: string;
  operatingWindow?: { start: string; end: string };
}

export interface AiScheduleCommandResult {
  intent: {
    date: string;
    roundNumbers: number[];
    startTime: string;
    endTime: string;
    minimumStartIntervalMinutes: number;
    timingModel: "MATCH_TOTAL" | "PER_SET" | "PER_HALF";
    needsReview: boolean;
    explanation: string;
  };
  preview: SchedulePlanPreview;
}

