import { expect, test } from '@playwright/test';
import * as XLSX from 'xlsx';

import {
  divisionFixture as division,
  fulfillApi,
  openManage,
  tournamentId,
} from './support/organizer-manage';

test('the introduction tab stays in the page column and opens no dialog', async ({ page }) => {
  await openManage(page, { tab: 'overview' });

  await expect(page.getByTestId('manage-introduction-panel')).toBeVisible();
  await expect(page.getByRole('dialog')).toHaveCount(0);
  await expect(page.getByTestId('manage-wide-overlay')).toHaveCount(0);
});

test('uses four top operation tabs and a compact left selector while keeping sponsors inline', async ({ page }) => {
  await page.setViewportSize({ width: 1600, height: 900 });
  const secondDivision = { ...division, id: 'synthetic-wide-division-second', name: 'Synthetic second division' };
  await openManage(page, { tab: 'overview', divisions: [division, secondDivision] });

  await expect(page.getByRole('dialog')).toHaveCount(0);
  await page.getByTestId('manage-tab-settings').click();
  await expect(page.getByRole('dialog')).toHaveCount(0);
  await page.getByTestId('manage-tab-sponsors').click();
  await expect(page.getByRole('dialog')).toHaveCount(0);
  await expect(page.locator('#sponsor-settings-heading')).toBeVisible();

  await page.getByTestId('manage-tab-registration').click();
  const overlay = page.getByTestId('manage-wide-overlay');
  const operationTabs = overlay.getByTestId('manage-wide-operation-tabs');
  const divisionSelector = overlay.getByTestId('manage-wide-division-selector');
  const content = overlay.getByTestId('manage-wide-content');
  const firstDivisionButton = divisionSelector.getByTestId(`manage-wide-division-${division.id}`);
  const secondDivisionButton = divisionSelector.getByTestId(`manage-wide-division-${secondDivision.id}`);

  await expect(overlay).toBeVisible();
  await expect(operationTabs.locator('button')).toHaveCount(4);
  await expect(operationTabs.getByTestId('manage-wide-tab-sponsors')).toHaveCount(0);
  await expect(operationTabs.getByTestId('manage-wide-tab-registration')).toHaveAttribute('aria-current', 'page');
  await expect(divisionSelector.getByText('Nội dung thi đấu', { exact: false })).toBeVisible();
  await expect(firstDivisionButton).toBeVisible();
  await expect(secondDivisionButton).toBeVisible();

  const operationTabsBox = await operationTabs.boundingBox();
  const divisionSelectorBox = await divisionSelector.boundingBox();
  const contentBox = await content.boundingBox();
  expect(operationTabsBox?.y).toBeLessThan(divisionSelectorBox?.y ?? Number.POSITIVE_INFINITY);
  expect(operationTabsBox?.y).toBeLessThan(contentBox?.y ?? Number.POSITIVE_INFINITY);
  expect(divisionSelectorBox?.x).toBeLessThan(contentBox?.x ?? Number.POSITIVE_INFINITY);

  await firstDivisionButton.click();
  await expect(firstDivisionButton).toHaveAttribute('aria-current', 'page');
  await expect(content.getByTestId(`manage-wide-division-content-${division.id}`)).toBeVisible();
  await expect(content.getByTestId(`manage-wide-division-content-${secondDivision.id}`)).toHaveCount(0);

  await secondDivisionButton.click();
  await expect(secondDivisionButton).toHaveAttribute('aria-current', 'page');
  await expect(content.getByTestId(`manage-wide-division-content-${secondDivision.id}`)).toBeVisible();
  await expect(content.getByTestId(`manage-wide-division-content-${division.id}`)).toHaveCount(0);

  await operationTabs.getByTestId('manage-wide-tab-bracket').click();
  await expect(overlay).toBeVisible();
  await expect(operationTabs.getByTestId('manage-wide-tab-bracket')).toHaveAttribute('aria-current', 'page');
  await expect.poll(() => new URL(page.url()).searchParams.get('tab')).toBe('bracket');
  await expect(content.locator('#manage-bracket-workspace')).toBeVisible();

  await operationTabs.getByTestId('manage-wide-tab-court_schedule').click();
  await expect(overlay).toBeVisible();
  await expect(operationTabs.getByTestId('manage-wide-tab-court_schedule')).toHaveAttribute('aria-current', 'page');
  await expect.poll(() => new URL(page.url()).searchParams.get('tab')).toBe('court_schedule');
  await expect(content.getByText('Chưa có sân thi đấu')).toBeVisible();
});

test('clicking outside an operation modal returns to introduction and clears the tab query', async ({ page }) => {
  await page.setViewportSize({ width: 1600, height: 900 });
  await openManage(page, { tab: 'registration' });

  await expect(page.getByTestId('manage-wide-overlay')).toBeVisible();
  await page.mouse.click(2, 2);

  await expect(page.getByTestId('manage-wide-overlay')).toHaveCount(0);
  await expect(page.getByTestId('manage-introduction-panel')).toBeVisible();
  await expect.poll(() => new URL(page.url()).searchParams.has('tab')).toBe(false);
});

test('keeps the two-pane modal usable on mobile and has a large close target', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 812 });
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await openManage(page, { tab: 'registration' });

  const overlay = page.getByTestId('manage-wide-overlay');
  const operationTabs = overlay.getByTestId('manage-wide-operation-tabs');
  const divisionSelector = overlay.getByTestId('manage-wide-division-selector');
  const content = overlay.getByTestId('manage-wide-content');
  await expect(operationTabs).toBeVisible();
  await expect(operationTabs.locator('button')).toHaveCount(4);
  await expect(divisionSelector.getByText('Nội dung thi đấu', { exact: false })).toBeVisible();
  await expect(content).toBeVisible();
  await expect(overlay).toHaveCSS('animation-name', 'none');

  const closeButton = overlay.getByRole('button', { name: 'Đóng' });
  const closeBox = await closeButton.boundingBox();
  const lastTabBox = await operationTabs.getByTestId('manage-wide-tab-livestream').boundingBox();
  expect(closeBox?.width).toBeGreaterThanOrEqual(44);
  expect(closeBox?.height).toBeGreaterThanOrEqual(44);
  expect(closeBox).not.toBeNull();
  expect(lastTabBox).not.toBeNull();
  expect(closeBox!.x).toBeGreaterThanOrEqual(lastTabBox!.x + lastTabBox!.width);
  await closeButton.click();
  await expect(overlay).toBeHidden();
});

test('the participant tab opens in a full-width dialog instead of the narrow column', async ({ page }) => {
  await page.setViewportSize({ width: 1600, height: 900 });
  await openManage(page);

  await page.getByTestId('manage-tab-registration').click();

  const overlay = page.getByTestId('manage-wide-overlay');
  await expect(overlay).toBeVisible();
  await expect(overlay).toHaveAttribute('role', 'dialog');
  await expect(overlay).toContainText(division.name);

  // The participant table only renders once its division is expanded.
  const divisionButton = page.getByRole('button', { name: new RegExp(division.name, 'i') });
…
});

