import { expect, test } from '@playwright/test';
import { fulfillApi, openManage, tournamentId } from './support/organizer-manage';

const divisionId = 'synthetic-wide-division';

test('organizer can add a directly entered guest with optional contact and note', async ({ page }) => {
  let addRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    await fulfillApi(route, { data: { rows: [], nextCursor: null } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, { data: { participant: { id: 'new-participant' } } }, 201);
  });
  await openManage(page, { tab: 'registration' });

  await expect(page.getByRole('button', { name: 'Import Excel' })).toBeVisible();
  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  await expect(dialog).toBeVisible();
  await dialog.getByRole('button', { name: 'Nhập trực tiếp' }).click();
  await dialog.getByLabel('Tên VĐV').fill('Guest Athlete');
  await dialog.getByLabel('Ghi chú ban tổ chức').fill('Arrives late');
  await dialog.getByRole('button', { name: 'Thêm vào giải' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'DIRECT',
    divisionId,
    players: [{ displayName: 'Guest Athlete', role: 'MAIN' }],
    organizerNote: 'Arrives late',
  });
  await expect(dialog).toBeHidden();
});

test('candidate search paginates and selecting a player does not expose contact information', async ({ page }) => {
  const queries: URL[] = [];
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    const url = new URL(route.request().url());
    queries.push(url);
    await fulfillApi(route, url.searchParams.get('cursor')
      ? { data: { rows: [], nextCursor: null } }
      : { data: { rows: [{ userId: 'friend-1', displayName: 'Friend Athlete', avatarUrl: null, source: 'FRIENDS' }], nextCursor: 'page-2' } });
  });
  await openManage(page, { tab: 'registration' });
  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  await dialog.getByRole('button', { name: 'Bạn bè' }).click();
  await dialog.getByLabel('Tìm VĐV').fill('Friend');
  await expect(dialog.getByText('Friend Athlete')).toBeVisible();
  await expect(dialog.getByText(/@|09\d{8}/)).toHaveCount(0);
  await dialog.getByRole('button', { name: 'Trang tiếp' }).click();
  await expect.poll(() => queries.some((url) => url.searchParams.get('cursor') === 'page-2')).toBe(true);
  expect(queries[0].searchParams.get('source')).toBe('FRIENDS');
});

