'use client';

import * as React from 'react';
import { useLocale, useTranslations } from 'next-intl';
import { AlertTriangle, Download, FileSpreadsheet, Info, ShieldAlert } from 'lucide-react';
import toast from 'react-hot-toast';

import { Button } from '@/components/ui/Button';
import {
  Modal,
  ModalContent,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalTitle,
} from '@/components/ui/Modal';
import { tournamentsApi, type Division, type RosterImportItem, type RosterPreviewRow } from '@/features/tournaments/api';
import type { Tournament } from '@/types/tournament';
import { getErrorMessage } from '@/utils/error';
import {
  detectRosterColumnMapping,
  downloadParticipantsTemplateExcel,
  parseRosterWorkbook,
  ROSTER_COLUMN_SLOTS,
  type RosterColumnSlot,
  type RosterSheet,
  type RosterSheetCandidate,
  type RosterWorkbook,
} from '@/utils/exportTournament';
import { RosterColumnMappingStep, type RosterAiReview } from './RosterColumnMappingStep';
import { RosterPreviewTable } from './RosterPreviewTable';
import {
  buildRosterDraftRows,
  toRosterImportItem,
  useRosterImportDraft,
  type RosterDraftRow,
} from './useRosterImportDraft';

/** Only a handful of rows are needed to recognise a header, and fewer rows is a cheaper ask. */
const AI_REVIEW_SAMPLE_ROWS = 8;

/** Both import endpoints bound each request to 200 participant rows. */
const IMPORT_BATCH_SIZE = 200;

const EMPTY_MAPPING = Object.fromEntries(
  ROSTER_COLUMN_SLOTS.map((slot) => [slot, '']),
) as Record<RosterColumnSlot, string>;

interface RosterImportModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tournament: Tournament;
  divisions: Division[];
  selectedDivisionId: string;
  onSuccess: () => Promise<void> | void;
}

export function RosterImportModal({
  open,
  onOpenChange,
  tournament,
  divisions,
  selectedDivisionId,
  onSuccess,
}: RosterImportModalProps) {
  const translate = useTranslations('RosterImport');
  const locale = useLocale();
  const fileRef = React.useRef<File | null>(null);
  // Parsing is asynchronous and the header-row field fires on every keystroke, so
  // a slow older parse must never overwrite a newer sheet/header choice.
  const sheetRequestRef = React.useRef(0);
  const [fileName, setFileName] = React.useState('');
  const [autoApprove, setAutoApprove] = React.useState(true);
  // A wildcard request is an organizer annotation (INV-005): the import never
  // grants a reserved slot, so bulk marking stays local until the commit.
  const [wildcardAll, setWildcardAll] = React.useState(false);
  // A preview belongs to the division it was requested for; switching division
  // must not leave the previous verdicts on screen.
  const [checkedDivisionId, setCheckedDivisionId] = React.useState('');
  // AI never touches the mapping on its own. It fills this, the organizer reads
  // it, and only the apply button writes anything back into the draft.
  const [aiReview, setAiReview] = React.useState<RosterAiReview | null>(null);
  // What the scanner tried, so the organizer can see it chose a sheet on
  // evidence rather than by luck. Empty once they pick a sheet themselves.
  const [sheetCandidates, setSheetCandidates] = React.useState<RosterSheetCandidate[]>([]);

  const initialDivisionId = selectedDivisionId || divisions[0]?.id || '';
  const [targetDivisionId, setTargetDivisionId] = React.useState(initialDivisionId);
  const targetDivision =
    divisions.find((division) => division.id === targetDivisionId) ?? null;
  const activeMatchType = targetDivision?.matchType ?? tournament.matchType;
  const isDoubles = activeMatchType === 'DOUBLES' || activeMatchType === 'MIXED_DOUBLES';
  const defaultPaid = Number(targetDivision?.entryFee ?? tournament.entryFee ?? 0) <= 0;

  const draftInit = React.useMemo(
    () => ({
      step: 'pick-file' as const,
      mapping: EMPTY_MAPPING,
      headerRow: 1,
      isDoubles,
    }),
    [isDoubles],
  );
  const { state, rowStates, eligibleRows, dispatch, reset: resetDraft } =
    useRosterImportDraft(draftInit);


  const invalidRows = state.rows.filter((row) => !rowStates.get(row.rowIndex)?.isEligible);
  const hasPreview = state.preview.length > 0 && checkedDivisionId === targetDivisionId;
  const foundCount = state.preview.filter((row) => row.status.includes('FOUND')).length;
  const guestCount = state.preview.filter((row) => row.status.includes('NOT_FOUND')).length;
  const capacityShortfall =
    state.capacityRemaining !== null && state.capacityRemaining < state.requestedTeamSlots;

  const loadSheet = React.useCallback(
    (workbook: RosterWorkbook, sheet: RosterSheet) => {
      const mapping = detectRosterColumnMapping(sheet.headers);
      dispatch({
        type: 'workbook-loaded',
        sheetNames: workbook.sheetNames,
        sheet,
        mapping,
        rows: buildRosterDraftRows(sheet, mapping, defaultPaid),
      });
    },
    [defaultPaid, dispatch],
  );

  const handleFileSelected = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
