'use client';

import * as React from 'react';
import { useTranslations } from 'next-intl';
import { Loader2, Search, UserPlus } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Textarea } from '@/components/ui/Textarea';
import { Modal, ModalContent, ModalDescription, ModalFooter, ModalHeader, ModalTitle } from '@/components/ui/Modal';
import { tournamentsApi, type AddAthleteCandidate, type AddAthleteSource, type Division } from '@/features/tournaments/api';
import type { Tournament } from '@/types/tournament';
import { getErrorMessage } from '@/utils/error';
import toast from 'react-hot-toast';

interface AddAthleteModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tournament: Tournament;
  divisions: Division[];
  selectedDivisionId: string;
  onSuccess: () => Promise<void> | void;
}

const SOURCES: AddAthleteSource[] = ['FRIENDS', 'CLUB', 'DIRECT'];

export function AddAthleteModal({ open, onOpenChange, tournament, divisions, selectedDivisionId, onSuccess }: AddAthleteModalProps) {
  const t = useTranslations('AddAthlete');
  const initialDivisionId = selectedDivisionId || divisions[0]?.id || '';
  const [divisionId, setDivisionId] = React.useState(initialDivisionId);
  const [source, setSource] = React.useState<AddAthleteSource>('FRIENDS');
  const [search, setSearch] = React.useState('');
  const [rows, setRows] = React.useState<AddAthleteCandidate[]>([]);
  const [nextCursor, setNextCursor] = React.useState<string | null>(null);
  const [selectedIds, setSelectedIds] = React.useState<string[]>([]);
  const [pageLoading, setPageLoading] = React.useState(false);
  const [submitting, setSubmitting] = React.useState(false);
  const [players, setPlayers] = React.useState([{ displayName: '', email: '', phone: '' }]);
  const [teamName, setTeamName] = React.useState('');
  const [organizerNote, setOrganizerNote] = React.useState('');
  const selectedDivision = divisions.find((division) => division.id === divisionId);
  const matchType = selectedDivision?.matchType ?? tournament.matchType;
  const maxPlayers = matchType === 'DOUBLES' || matchType === 'MIXED_DOUBLES' ? 2 : 1;

  const loadCandidates = React.useCallback(async (cursor?: string, append = false) => {
    if (source === 'DIRECT' || !open) return;
    setPageLoading(true);
    try {
      const response = await tournamentsApi.getAddAthleteCandidates(tournament.id, {
        source,
        divisionId: divisionId || undefined,
        search: search.trim() || undefined,
        cursor,
        limit: 20,
      });
      const payload = response.data?.data ?? response.data;
      setRows((current) => append ? [...current, ...(payload?.rows ?? [])] : (payload?.rows ?? []));
      setNextCursor(payload?.nextCursor ?? null);
    } catch (error) {
      toast.error(getErrorMessage(error));
      if (!append) setRows([]);
      setNextCursor(null);
    } finally {
      setPageLoading(false);
    }
  }, [divisionId, open, search, source, tournament.id]);

  React.useEffect(() => {
    if (open && source !== 'DIRECT') void loadCandidates();
  }, [loadCandidates, open, source]);

  React.useEffect(() => {
    if (!open) return;
    setDivisionId(initialDivisionId);
    setSource('FRIENDS');
    setSearch('');
    setSelectedIds([]);
    setPlayers(Array.from({ length: maxPlayers }, () => ({ displayName: '', email: '', phone: '' })));
    setTeamName('');
    setOrganizerNote('');
  }, [initialDivisionId, maxPlayers, open]);

  const switchSource = (value: AddAthleteSource) => {
    setSource(value);
    setSelectedIds([]);
    setRows([]);
    setNextCursor(null);
  };

  const submit = async () => {
    if (submitting) return;
    if (source === 'DIRECT' && players.some((player) => !player.displayName.trim())) return;
    if (source !== 'DIRECT' && selectedIds.length !== maxPlayers) return;
    setSubmitting(true);
    try {
      const response = await tournamentsApi.addAthletes(tournament.id, {
        source,
        ...(divisionId ? { divisionId } : {}),
        ...(teamName.trim() ? { teamName: teamName.trim() } : {}),
        players: source === 'DIRECT'
          ? players.map((player, index) => ({
              displayName: player.displayName.trim(),
              ...(player.email.trim() ? { email: player.email.trim() } : {}),
              ...(player.phone.trim() ? { phone: player.phone.trim() } : {}),
              role: index === 0 ? 'MAIN' as const : 'PARTNER' as const,
            }))
          : selectedIds.map((userId, index) => ({ userId, role: index === 0 ? 'MAIN' as const : 'PARTNER' as const })),
        ...(organizerNote.trim() ? { organizerNote: organizerNote.trim().slice(0, 280) } : {}),
      });
      if (!response.data) throw new Error(t('addFailed'));
      const payload = response.data.data ?? response.data;
      const claimToken = payload?.claim?.claimToken;
      if (claimToken) window.prompt(t('claimTokenHandoff'), claimToken);
      toast.success(t('addSuccess'));
      onOpenChange(false);
      await onSuccess();
    } catch (error) {
      toast.error(getErrorMessage(error));
    } finally {
      setSubmitting(false);
    }
  };

  const canSubmit = source === 'DIRECT'
    ? players.every((player) => player.displayName.trim().length > 0)
    : selectedIds.length === maxPlayers;

  return (
    <Modal open={open} onOpenChange={onOpenChange}>
      <ModalContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl" aria-describedby="add-athlete-description">
        <ModalHeader>
          <ModalTitle>{t('title')}</ModalTitle>
          <ModalDescription id="add-athlete-description">{t('description')}</ModalDescription>
        </ModalHeader>
        <div className="space-y-4">
          {divisions.length > 1 && <div>
            <label htmlFor="add-athlete-division" className="mb-1 block text-sm font-medium">{t('division')}</label>
            <select id="add-athlete-division" value={divisionId} onChange={(event) => { setDivisionId(event.target.value); setSelectedIds([]); }} className="h-10 w-full rounded-md border border-slate-300 bg-white px-3 text-sm">
              {divisions.map((division) => <option key={division.id} value={division.id}>{division.name}</option>)}
            </select>
          </div>}
          <div role="tablist" aria-label={t('source')} className="flex flex-wrap gap-2">
            {SOURCES.map((option) => <button key={option} type="button" role="tab" aria-selected={source === option} onClick={() => switchSource(option)} className={`min-h-10 rounded-md border px-3 text-sm font-medium focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${source === option ? 'border-blue-600 bg-blue-50 text-blue-800' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}>{t(`source${option}`)}</button>)}
          </div>
          {source !== 'DIRECT' ? <>
            <label className="relative block">
              <span className="sr-only">{t('search')}</span>
              <Search aria-hidden="true" className="absolute left-3 top-3 h-4 w-4 text-slate-400" />
              <Input aria-label={t('search')} value={search} onChange={(event) => setSearch(event.target.value)} className="pl-9" placeholder={t('search')} />
            </label>
            <div aria-live="polite" aria-busy={pageLoading} className="max-h-64 space-y-1 overflow-y-auto rounded-md border border-slate-200 p-2">
              {pageLoading && rows.length === 0 ? <p className="p-4 text-center text-sm text-slate-500"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />{t('loading')}</p> : rows.length === 0 ? <p className="p-4 text-center text-sm text-slate-500">{t('empty')}</p> : rows.map((candidate) => (
                <label key={candidate.userId} className="flex cursor-pointer items-center gap-3 rounded-md p-2 hover:bg-slate-50">
                  <input type="checkbox" checked={selectedIds.includes(candidate.userId)} disabled={!selectedIds.includes(candidate.userId) && selectedIds.length >= maxPlayers} onChange={() => setSelectedIds((current) => current.includes(candidate.userId) ? current.filter((id) => id !== candidate.userId) : [...current, candidate.userId])} />
                  {candidate.avatarUrl ? <img src={candidate.avatarUrl} alt="" className="h-9 w-9 rounded-full object-cover" /> : <span aria-hidden="true" className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-blue-100 text-sm font-semibold text-blue-700">{candidate.displayName.trim().split(/\s+/).map((part) => part[0]).slice(-2).join('').toUpperCase()}</span>}
                  <span className="text-sm font-medium">{candidate.displayName}</span>
                </label>
              ))}
              {nextCursor && <Button type="button" variant="outline" size="sm" disabled={pageLoading} onClick={() => void loadCandidates(nextCursor, true)} className="w-full">{t('nextPage')}</Button>}
            </div>
            <p className="text-xs text-slate-500">{t('selectedCount', { selected: selectedIds.length, required: maxPlayers })}</p>
          </> : <>
            {players.map((player, index) => <div key={index} className="grid gap-3 rounded-md border border-slate-200 p-3 sm:grid-cols-3">
              <div><label htmlFor={`add-athlete-name-${index}`} className="mb-1 block text-sm font-medium">{t('name')} <span aria-hidden="true">*</span></label><Input id={`add-athlete-name-${index}`} required value={player.displayName} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, displayName: event.target.value } : item))} /></div>
              <div><label htmlFor={`add-athlete-email-${index}`} className="mb-1 block text-sm font-medium">{t('email')}</label><Input id={`add-athlete-email-${index}`} type="email" value={player.email} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, email: event.target.value } : item))} /></div>
              <div><label htmlFor={`add-athlete-phone-${index}`} className="mb-1 block text-sm font-medium">{t('phone')}</label><Input id={`add-athlete-phone-${index}`} type="tel" value={player.phone} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, phone: event.target.value } : item))} /></div>
            </div>)}
          </>}
          <div><label htmlFor="add-athlete-team-name" className="mb-1 block text-sm font-medium">{t('teamName')}</label><Input id="add-athlete-team-name" value={teamName} onChange={(event) => setTeamName(event.target.value)} /></div>
          <div><label htmlFor="add-athlete-organizer-note" className="mb-1 block text-sm font-medium">{t('organizerNote')}</label><Textarea id="add-athlete-organizer-note" maxLength={280} rows={3} value={organizerNote} onChange={(event) => setOrganizerNote(event.target.value)} /><p className="mt-1 text-right text-xs text-slate-500">{organizerNote.length}/280</p></div>
          <p role="status" aria-live="polite" className="sr-only">{pageLoading ? t('loading') : ''}</p>
        </div>
